    fn timer_handle_method(kind: BuiltinFunctionKind, handle_object: ObjectId) -> Self {
        Self {
            kind,
            module_specifier: String::new(),
            iterator_handle: None,
            bound_object: Some(handle_object.0),
        }
    }

